<template>
	<view class="app-icon" :style="{ width: size + 'rpx', height: size + 'rpx', backgroundImage: bg }"></view>
</template>

<script>
/**
 * 「简记」线性图标：24 viewBox / 2px 圆头笔画，统一墨灰两档 + 语义红。
 * 以 base64 SVG data-URI 作背景图渲染，H5 与微信小程序通用（小程序
 * WXSS 不支持内联 <svg>，background-image 的 data URI 两端都可靠）。
 * 颜色已烘进 SVG，不能运行时改色；需要新色值时在 ICONS 里加变体。
 * 小程序环境没有 btoa，图标统一用预生成的 base64 串，不做运行时编码。
 */
const ICONS = {
	receipt: '',
	compose: '',
	history: '',
	filter: 'PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIyNCIgaGVpZ2h0PSIyNCIgdmlld0JveD0iMCAwIDI0IDI0IiBmaWxsPSJub25lIiBzdHJva2U9IiM1MjUyNUIiIHN0cm9rZS13aWR0aD0iMiIgc3Ryb2tlLWxpbmVjYXA9InJvdW5kIiBzdHJva2UtbGluZWpvaW49InJvdW5kIj48cGF0aCBkPSJNMjIgM0gybDggOS40NlYxOWw0IDJ2LTguNTR6Ii8+PC9zdmc+',
	lock: '',
	'lock-ink': '',
	logout: '',
	camera: '',
	edit: '',
	alert: '',
	back: 'PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIyNCIgaGVpZ2h0PSIyNCIgdmlld0JveD0iMCAwIDI0IDI0IiBmaWxsPSJub25lIiBzdHJva2U9IiM1MjUyNUIiIHN0cm9rZS13aWR0aD0iMiIgc3Ryb2tlLWxpbmVjYXA9InJvdW5kIiBzdHJva2UtbGluZWpvaW49InJvdW5kIj48cGF0aCBkPSJtMTUgMTgtNi02IDYtNiIvPjwvc3ZnPg==',
	trend: '',
	bot: '',
	/* 话筒：常态墨灰 #52525B / 录音中语义红 #E5484D（与 logout、alert 同色系） */
	mic: '',
	'mic-rec': '',
	/* 会员模块：皇冠（琥珀 deep=档位主视觉 / 墨=我的页入口 / 灰=免费档）、礼包（兑换）、
	   对话气泡 / 柱状图 / 闪电（用量与权益行），与既有集合同规格（24 viewBox / 2px 圆头） */
	'crown-amber': '',
	'crown-ink': '',
	'crown-muted': '',
	gift: '',
	chat: '',
	chart: '',
	bolt: '',
}

export default {
	name: 'AppIcon',
	props: {
		/** 图标名，见 ICONS 表 */
		name: { type: String, required: true },
		/** 尺寸（rpx，正方形） */
		size: { type: [Number, String], default: 40 },
	},
	computed: {
		bg() {
			const encoded = ICONS[this.name]
			return encoded ? `url("data:image/svg+xml;base64,${encoded}")` : ''
		},
	},
}
</script>

<style scoped>
.app-icon {
	display: inline-block;
	background-repeat: no-repeat;
	background-position: center;
	background-size: 100% 100%;
}
</style>
